                /**
                Namespace reg.udral.service.common
                */
                public struct common {

                    /**
                    The function of the service heartbeat is similar to that of the node heartbeat defined in the standard
                    namespace, except that it is used on a per-service basis, meaning that there may be more than one publisher
                    per node.
                    The service heartbeat should be published either on a separate subject, or as a structural supertype of a
                    service-specific status subject. The publication rate is service-specific but it should not be lower than 1
                    Hz.
                    This is a structural subtype of the Readiness type.
                    */
                    [Version(0, 1), Sealed]
                    public class Heartbeat_0_1 {
                        /**
                        Any service that is not in the SLEEP state should publish its heartbeat (or a derived status) at least at this
                        rate.
                        */
                        public const byte MAX_PUBLICATION_PERIOD = 1;
                        udral.service.common.Readiness_0_1 readiness;
                        uavcan.node.Health_1_0 health;
                    }

                    /**
                    The readiness state is used to command or report the availability status of a networked service (subsystem).
                    Any system shall have at least one readiness command subject that acts as a global power switch. Every
                    subsystem controlled in such way would usually report its readiness status back to account for the fact that
                    the transition between different readiness states may not be instantaneous. The readiness status reporting is
                    done by means of the service heartbeat type that is also defined in this namespace; the service heartbeat type
                    is a structural subtype of this type.
                    +------------+ | Controller |----------+----------------+----------------+---------...     readiness command
                    subject +------------+          |                |                | ^   ^   ^             v                v  
                                 v |   |   |        +---------+      +---------+      +---------+ |   |   |        | Service |    
                     | Service |      | Service |    ... |   |   |        +---------+      +---------+      +---------+ |   |   | 
                               |                |                | |   |   +-------------+                |                | |  
                    +----------------------------------+                |                 service heartbeat subjects
                    +-------------------------------------------------------+
                    In a less trivial use case there may be an arbitrary number of such readiness command subjects (local power
                    switches) controlling various systems within the vehicle (e.g., propulsion, perception sensors, communication,
                    etc).
                    The publication rate is defined on a per-service basis, but it should never be lower than 1 Hz, excepting
                    services that are in the SLEEP state, in which case it is permitted to cease all network activity.
                    */
                    [Version(0, 1), Sealed]
                    public class Readiness_0_1 {
                        /**
                        The long-term state of minimal power consumption. Typically, most subsystems are switched into the SLEEP mode
                        when the vehicle is parked and powered off. Subsystems that do not support the SLEEP state should treat it as
                        an equivalent of STANDBY. A subsystem may require a substantial amount of time to exit the sleep mode (for
                        example, time may be needed to boot the operating system and run the self test procedures). While in the SLEEP
                        mode, the subsystem is allowed to cease service provision and stop all network activity regardless of other
                        requirements, except that it shall be able to reactivate itself if a Readiness message is received commanding
                        any state other than SLEEP.
                        */
                        public const byte SLEEP = 0;
                        /**
                        The state of being ready to enter the normal operating mode in a short order. A subsystem that is in STANDBY
                        state should be able to participate in the normal network activity. This is the default state that the
                        subsystem should reside in after power-on until explicitly commanded otherwise.
                        */
                        public const byte STANDBY = 2;
                        /**
                        When ENGAGED, the subsystem is performing its main intended function at the nominal performance
                        characteristics. A subsystem may require a short amount of time, possibly under a few seconds, to switch
                        between the ENGAGED and STANDBY states (in any direction). Some subsystems may not differentiate between
                        STANDBY and ENGAGED (e.g., offboard communication hardware). The subsystem may disengage itself autonomously
                        in the event of a fatal malfunction, in which case the reported service health status should be WARNING.
                        */
                        public const byte ENGAGED = 3;
                        [CastMode("truncated"), MinMax(0, 3)] byte value;
                    }
                }

                /**
                Namespace reg.udral.service.sensor
                */
                public struct sensor {

                    /**
                    A generic sensor status information. This data should be published at a low rate but not lower than the
                    specified limit.
                    */
                    [Version(0, 1), Extent(63)]
                    public class Status_0_1 {
                        /**
                        [second]
                        */
                        public const byte MAX_PUBLICATION_PERIOD = 1;
                        /**
                        Data samples obtained at time Ts are valid at time Tr if: (Tr - Ts) &lt; data_validity_period Expired data
                        should be discarded. DSDL type uavcan.si.unit.duration.Scalar (a duration in seconds) is modelled as an AdHoc
                        Duration.
                        */
                        DurationSeconds data_validity_period;
                        /**
                        Incremented once per occurrence. Reset to zero when the sensor is ENGAGED. The exact definition of what
                        constitutes an error is implementation-dependent.
                        */
                        uint error_count; // physics: monotonic and large (counter/uptime/sequence) → varint LOSES past 268 435 455; keep fixed width
                        /**
                        The temperature of the sensing element. If there are multiple sensing elements or multiple temperature probes
                        per sensor, the reduction is implementation-defined. In a later revision this field may be moved into a
                        separate type.
                        */
                        uavcan.si.unit.temperature.Scalar_1_0 sensor_temperature;
                    }
                }
            }
        }

